  "sync.offline": "କେବଳ ଏହି ଡିଭାଇସ୍‌ରେ",
  "case.sampleTitle": "ଏହା ଏକ ନମୁନା ମାମଲା, ଆପଣଙ୍କର ନୁହେଁ",
  "case.sampleBody": "ଏହା ମୁଖ୍ୟ ପୃଷ୍ଠାରେ ଥିବା ରେକର୍ଡ ହୋଇଥିବା କଲ୍‌ରୁ ତିଆରି ହୋଇଥିଲା, ସେହି ସେହି କୋଡ଼ ଦ୍ୱାରା ଯାହା ଏକ ପ୍ରକୃତ କଲ୍ ଚାଲିଥାଏ — ଏହାକୁ ଅଧିକ ଭଲ ଦେଖାଯିବା ପାଇଁ ହାତରେ କିଛି ଲେଖାଯାଇ ନାହିଁ। ଏହାର କୌଣସି ଅଂଶ ଜଣେ ପ୍ରକୃତ ବ୍ୟକ୍ତିଙ୍କର ନୁହେଁ। ଏହା କେବଳ ଏହି ଡିଭାଇସ୍‌ରେ ସଂରକ୍ଷିତ ହୋଇଛି, ଏବଂ ଆପଣ ଏହାକୁ ଯେକୌଣସି ଅନ୍ୟ ମାମଲା ପରି ଏଡିଟ୍ କିମ୍ବା ଡିଲିଟ୍ କରିପାରିବେ।",
  "case.sampleListen": "ଏହା କେଉଁ କଲ୍‌ରୁ ଆସିଛି ଶୁଣନ୍ତୁ",
  "build.h1": "ଆଉ କିଛି କଥା",
  "build.sub": "କେବଳ ସେତିକି ଯାହା ପୋଲିସ ଏବଂ ଆପଣଙ୍କ ବ୍ୟାଙ୍କ ପ୍ରକୃତରେ ପଚାରିବେ। ଆପଣ ଟାଇପ୍ କରିବା ସମୟରେ ସବୁକିଛି ସଂରକ୍ଷିତ ହୋଇଯାଏ।",
