  "build.evidence.b": "SMS, WhatsApp ମେସେଜ୍, ଇମେଲ୍, ବ୍ୟାଙ୍କ ଆଲର୍ଟ। ମୂଳ ଟେକ୍ସଟ୍‌କୁ ପେଷ୍ଟ କରନ୍ତୁ — ଆମେ ଦରକାରୀ ନମ୍ବରଗୁଡ଼ିକୁ ବାହାର କରିଦେବୁ ଏବଂ ଆପଣଙ୍କୁ ସେଗୁଡ଼ିକ ଟାଇପ୍ କରିବାକୁ ପଡ଼ିବ ନାହିଁ।",
