  "f.mobile.why": "ଏକ ସରକାରୀ ସେବା ଯାଞ୍ଚ କିମ୍ବା ଯୋଗାଯୋଗ ପାଇଁ ଏହି ନମ୍ବର ବ୍ୟବହାର କରିପାରେ। Kavach ଏହି ପ୍ରଟୋଟାଇପ୍ ରେ ଏହାକୁ କୌଣସି ସ୍ଥାନକୁ ପଠାଏ ନାହିଁ।",
  "f.mobile.was": "ପୋର୍ଟାଲରେ ଏହା ପ୍ରଥମେ ଆସେ: OTP ଦ୍ୱାରା ମୋବାଇଲ୍ ନମ୍ବର ଯାଞ୍ଚ ନ ହେବା ପର୍ଯ୍ୟନ୍ତ କୌଣସି ଅଭିଯୋଗ ଆରମ୍ଭ କରାଯାଇପାରିବ ନାହିଁ, ଏବଂ ଯେତେବେଳେ ଆପଣ ଚାଳିଶୋଟି ଫିଲ୍ଡ ପୂରଣ କରୁଥାଆନ୍ତି, ସେତେବେଳେ OTP ପଚିଶି ମିନିଟ୍ ମଧ୍ୟରେ ଏକ୍ସପାୟାର୍ ହୋଇଯାଏ।",
  "f.email": "ଇମେଲ୍",
  "f.gender": "ଲିଙ୍ଗ",
  "f.gender.was": "ପୋର୍ଟାଲରେ ବାଧ୍ୟତାମୂଳକ। ଏହି ଫିଲ୍ଡଟି ଏଣ୍ଟ୍ରି ଏବଂ ସବ୍ମିଶନ୍ ମଧ୍ୟରେ ନିଜର ମୂଲ୍ୟ ବଦଳାଇବାର ଏକ ଲିପିବଦ୍ଧ ରିପୋର୍ଟ ଅଛି।",
  "f.dob": "ଜନ୍ମ ତାରିଖ",
  "f.guardianName": "ବାପା, ମାଆ କିମ୍ବା ସ୍ୱାମୀ/ସ୍ତ୍ରୀଙ୍କ ନାମ",
  "f.guardianName.why": "ଏହା ପୋଲିସ ରେକର୍ଡରେ ଆପଣଙ୍କୁ ଚିହ୍ନଟ କରେ, ଯେଉଁଠାରେ ନାମଗୁଡ଼ିକ ପୁନରାବୃତ୍ତି ହୁଏ।",
  "f.guardianName.was": "ପୋର୍ଟାଲରେ ବାଧ୍ୟତାମୂଳକ। ଏହା ବିନା ଠକେଇ ଅଭିଯୋଗ ସବ୍ମିଟ୍ ହେବ ନାହିଁ।",
