  "f.nationalId": "ପରିଚୟ ପତ୍ର",
  "f.nationalId.why": "ଗ୍ରହଣ କରାଯାଇଥିବା ପୋର୍ଟାଲ ଚେକ୍ଲିଷ୍ଟ ଏକ ପରିଚୟ ଡକ୍ୟୁମେଣ୍ଟ ପାଇଁ ଅନୁରୋଧ କରେ। Kavach ପରିଚୟ ଡକ୍ୟୁମେଣ୍ଟ ସଂଗ୍ରହ କରେ ନାହିଁ। କେବଳ ବର୍ତ୍ତମାନର ସରକାରୀ ଚ୍ୟାନେଲ ବ୍ୟବହାର କରନ୍ତୁ, ସର୍ବନିମ୍ନ ଆବଶ୍ୟକୀୟ ତଥ୍ୟ ପ୍ରକାଶ କରନ୍ତୁ, ଏବଂ କୌଣସି ଯାଞ୍ଚ କରାଯାଇନଥିବା ଯୋଗାଯୋଗକୁ ID କପି କେବେବି ପଠାନ୍ତୁ ନାହିଁ।",
  "f.nationalId.was": "ଏକ ବାଧ୍ୟତାମୂଳକ ଅପଲୋଡ୍।",
