  "g.aiNote": "ଆପଣ ଆମକୁ ଯାହା କହିଥିଲେ ତାହା ଆଧାରରେ AI ଦ୍ୱାରା ଲିଖିତ। ଏହାକୁ ପଠାଇବା ପୂର୍ବରୁ ପଢ଼ି ନିଅନ୍ତୁ।",
  "g.offline": "ଆପଣ ଅଫଲାଇନ୍ ଅଛନ୍ତି। ଆପଣ ପ୍ରବେଶ କରିଥିବା ସମସ୍ତ ଜିନିଷ ସଂରକ୍ଷିତ ହୋଇରହିଛି।",
