  "g.demoMode": "ଡେମୋ ମୋଡ୍ — କୌଣସି AI କି କନଫିଗର୍ ହୋଇନାହିଁ, ତେଣୁ ଉତ୍ତରଗୁଡ଼ିକ ଏକ ବିଲ୍ଟ-ଇନ୍ ରୁଲ୍ ଏଞ୍ଜିନ୍ ରୁ ଆସୁଛି।",
