  "intake.title": "ଥରେ କୁହନ୍ତୁ। ଆମେ ଆପଣଙ୍କ ସହିତ ମାମଲା ତିଆରି କରୁ।",
  "intake.sub": "ଏକ ଶାନ୍ତ, ପ୍ରଶ୍ନ-ପରେ-ପ୍ରଶ୍ନ ସାକ୍ଷାତକାର। ପୁନର୍ବାର ଆରମ୍ଭ ନ କରି ଚାଟ୍, WhatsApp ପ୍ରିଭ୍ୟୁ ଏବଂ Vaani କଲ୍ ମଧ୍ୟରେ ମାର୍ଚ୍ଚ କରନ୍ତୁ।",
