  "intake.rbiScreenOnly": "ମାର୍ଗଦର୍ଶନ, ନିଷ୍ପତ୍ତି ନୁହେଁ",
  "intake.rbiDisclaimer": "ଏହି ସ୍କ୍ରିନ୍ କେବଳ ଅନଧିକୃତ ଇଲେକ୍ଟ୍ରୋନିକ୍ ବ୍ୟାଙ୍କିଙ୍ଗ୍ ଲେଣଦେଣ ପାଇଁ RBI/2017-18/15 ପ୍ରୟୋଗ କରେ। ବ୍ୟାଙ୍କ ତଥ୍ୟ ନିର୍ଦ୍ଧାରଣ କରିବା ଉଚିତ୍; ଅନ୍ୟ ପ୍ରତିକାରଗୁଡ଼ିକ ଏବେ ବି ରହିଥାଇପାରେ।",
  "intake.rbiSource": "ଅଫିସିଆଲ୍ RBI ସର୍କୁଲାର ପଢ଼ନ୍ତୁ",
  "intake.rbiContinue": "ମୁଁ ଏହା ପଢ଼ିଛି — ଜାରି ରଖନ୍ତୁ",
  "intake.rbiProtectionZero": "ଉତ୍ତରଗୁଡ଼ିକ ଏକ ସର୍ତ୍ତମୂଳକ ଶୂନ୍ୟ-ଦାୟିତ୍ୱ ପଥରେ ଖାପ ଖାଏ",
  "intake.rbiProtectionLimited": "ଉତ୍ତରଗୁଡ଼ିକ ଏକ ସୀମିତ-ଦାୟିତ୍ୱ ପଥରେ ଖାପ ଖାଏ",
  "intake.rbiProtectionPolicy": "ବ୍ୟାଙ୍କର ପ୍ରକାଶିତ ନୀତି ନିୟନ୍ତ୍ରଣ କରିପାରେ",
  "intake.rbiProtectionPostReport": "ସମ୍ଭାବ୍ୟ ଗ୍ରାହକ-ଅବହେଳା ପଥ; ବ୍ୟାଙ୍କ କାରଣ ପ୍ରମାଣ କରିବା ଜରୁରୀ",
  "intake.rbiProtectionNotApplicable": "ଏହି ସର୍କୁଲାର ଏକ ଅନୁମୋଦିତ ଦେୟକୁ କଭର୍ ନକରିପାରେ",
  "intake.rbiProtectionUnknown": "ସର୍କୁଲାର ପ୍ରୟୋଗ କରିବା ପୂର୍ବରୁ ଅଧିକ ତଥ୍ୟ ଆବଶ୍ୟକ",
  "intake.evidenceQ": "ଏଗୁଡ଼ିକ ମଧ୍ୟରୁ କେଉଁଟି ଆପଣଙ୍କ ପାଖରେ ଏବେ ବି ଅଛି?",
  "intake.evidenceSub": "ଯଦି ଏହା ନିରାପଦ, ତେବେ ମୂଳ ଚାଟ୍, ଲେଣଦେଣ ରେକର୍ଡ, ହେଡର୍ କିମ୍ବା କଲ୍ ଲଗ୍ ସଂରକ୍ଷଣ କରନ୍ତୁ। ଜରୁରୀ ସହାୟତାରେ ବିଳମ୍ବ କରନ୍ତୁ ନାହିଁ କିମ୍ବା କେବଳ ପ୍ରମାଣ ସଂଗ୍ରହ କରିବା ପାଇଁ କୌଣସି ଧମକପୂର୍ଣ୍ଣ ସମ୍ପର୍କ ସହିତ ଜଡ଼ିତ ରୁହନ୍ତୁ ନାହିଁ। ଆପଣ ପରବର୍ତ୍ତୀ ସମୟରେ ସ୍ଥାନୀୟ କେସ୍ ଭଲ୍ଟରେ ଫାଇଲ୍ ସଂଲଗ୍ନ କରିପାରିବେ।",
  "intake.evTransaction": "ଲେଣଦେଣ ସ୍କ୍ରିନସଟ୍ କିମ୍ବା ବିବରଣୀ",
  "intake.evBank": "ବ୍ୟାଙ୍କ SMS କିମ୍ବା ବିଜ୍ଞପ୍ତି",
  "intake.evReference": "UTR କିମ୍ବା ଦେୟ ସନ୍ଦର୍ଭ",
