  "intake.routingQ": "ମାମଲାଟି କେଉଁଆଡ଼େ ପଠାଯିବା ଉଚିତ୍?",
  "intake.routingSub": "ବର୍ତ୍ତମାନ ପାଇଁ ରାଜ୍ୟ ଯଥାପର୍ଯ୍ୟନ୍ତ ଅଟେ। ଜିଲ୍ଲା ସଠିକ୍ ପୋଲିସ ଏବଂ ବୃଦ୍ଧି ବିବରଣୀ ପ୍ରସ୍ତୁତ କରିବାରେ ଆମକୁ ସାହାଯ୍ୟ କରେ। ଏହା ଆପଣଙ୍କ ଅବସ୍ଥାନ ସେୟାର କରେ ନାହିଁ।",
