  "detail.intro": "କଠିନ କାମଟି ସରିଗଲା। ଏବଂ ଏବେ କିଛି ସଂକ୍ଷିପ୍ତ ପ୍ରଶ୍ନ, ଏବଂ ଆପଣ ପଠାଇବା ମାତ୍ରେ ପ୍ରତ୍ୟେକ ଉତ୍ତର ଏହି ଚାଟ୍ ପାଖରେ ଥିବା କେସ୍ ଫାଇଲରେ ଯାଇ ଜମା ହେବ।",
  "detail.introOptional": "ଏହା ଦ୍ୱାରା ଆପଣଙ୍କ ଚିଠିଗୁଡ଼ିକ ଖାଲି ସ୍ଥାନରେ ଭର୍ତ୍ତି କରିବା ବଦଳରେ ସମ୍ପୂର୍ଣ୍ଣ ପ୍ରସ୍ତୁତ ହୋଇ ବାହାରିଥାଏ। ଏଗୁଡ଼ିକ ମଧ୍ୟରୁ ଯେକୌଣସିଟିକୁ ଏଡ଼ାଇ ଯାଆନ୍ତୁ — ଆପଣ ଏଗୁଡ଼ିକୁ ପରେ ଯୋଡ଼ି ପାରିବେ।",
