  "detail.done": "ମୁଁ ପଚାରି ପାରିବା ଭଳି ଏହା ସବୁକିଛି ଅଟେ। ଆପଣଙ୍କ ଡକ୍ୟୁମେଣ୍ଟଗୁଡ଼ିକ ଏଗୁଡ଼ିକ ପୂର୍ବରୁ ଭର୍ତ୍ତି ହୋଇ ବାହାରିବ।",
