  "detail.nameWhy": "ଯଦି ସମ୍ଭବ ଆପଣଙ୍କ ବ୍ୟାଙ୍କରେ ଥିବା ବନାନ ଅନୁଯାୟୀ ଲେଖନ୍ତୁ: ଏଠାରେ ଆପଣ ଯେଉଁ ଅକ୍ଷର ବାଦ ଦେବେ ତାହା ଏଥିରେ ସ୍ୱାକ୍ଷରିତ ହେବ, ଏବଂ ବ୍ୟାଙ୍କ ଏହାକୁ ଆକାଉଣ୍ଟ ସହିତ ଯାଞ୍ଚ କରିବ।",
