  "ev.overviewDisclaimer": "ଯାଞ୍ଚତାଲିକା ସମ୍ପୂର୍ଣ୍ଣ ହେବା ଏହାର ପ୍ରମାଣ ନୁହେଁ ଯେ ପ୍ରମାଣଟି ପ୍ରକୃତ, ପର୍ଯ୍ୟାପ୍ତ କିମ୍ବା Kavach ରେ ସଂରକ୍ଷିତ ଅଛି।",
